-- =============================================================================
-- dispatch-service 참조 데이터 시드 (DESIGN.md §5.3, Phase 3-5a)
--
-- 반복 마이그레이션이다. 체크섬이 바뀌면 다시 돌고, 모든 INSERT 는 ON CONFLICT 로 갱신한다 —
-- 통합 테스트가 시드를 자동으로 얻고, 두 번 돌려도 같은 행이 남는다.
--
-- **룰 행은 contracts/seed/dispatch-rules.json 에서 생성했다.** 손으로 옮기면 갈라지고,
-- 갈라진 날 "테스트는 통과하는데 운영 룰이 다르다" 가 된다. 두 파일이 같은지는
-- DispatchSeedCoverageIT 가 검사한다 (contracts/seed/order-service-geohash5.txt 와 같은 방식).
--
-- camp_id 는 fulfillment 의 camps.id 를 **값으로만** 들고 있다 (불변규칙 3 — 서비스 간 FK 금지).
-- 두 시드가 같은 UUID 를 쓰는지도 위 IT 가 검사한다.
-- =============================================================================

-- --- 룰 (전역, camp_id IS NULL) ----------------------------------------------

INSERT INTO dispatch_rules (id, camp_id, name, type, severity, params, priority, enabled, rule_version, updated_at) VALUES
