ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name, type = EXCLUDED.type, severity = EXCLUDED.severity,
  params = EXCLUDED.params, priority = EXCLUDED.priority, enabled = EXCLUDED.enabled,
  rule_version = EXCLUDED.rule_version, updated_at = EXCLUDED.updated_at;

-- --- 차량 200대 (캠프 10 × 20대) ---------------------------------------------
--
-- 밴 14 · 트럭 6. 냉장은 트럭 전부와 밴 일부, 위험물 허용은 10대 중 1대다 — 하드 룰이 실제로
-- 배정을 바꾸되 막다른 길은 아니어야 한다(§6.3). 자전거를 넣지 않는 이유는 벤치마크에서 잰
